import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    XBORNID c;

    function setUp() public {
        c = new XBORNID();
    }

    function _run(uint256 sendAmount) internal {
        sendAmount = bound(sendAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= sendAmount);
        uint256 beforeCallerBalance;
        try c.balanceOf(address(this)) returns (uint256 __r) { beforeCallerBalance = __r; } catch { return; }
        uint256 beforeTotalDistributed;
        try c.totalDistributed() returns (uint256 __r) { beforeTotalDistributed = __r; } catch { return; }
        uint256 beforeTotalRemaining;
        try c.totalRemaining() returns (uint256 __r) { beforeTotalRemaining = __r; } catch { return; }
        bool beforeBlacklist;
        try c.blacklist(address(this)) returns (bool __r) { beforeBlacklist = __r; } catch { return; }
        bool didRevert;
        try c.getTokens{value: sendAmount}() {
            didRevert = false;
        } catch {
            didRevert = true;
        }
        uint256 afterCallerBalance;
        try c.balanceOf(address(this)) returns (uint256 __r) { afterCallerBalance = __r; } catch { return; }
        uint256 afterTotalDistributed;
        try c.totalDistributed() returns (uint256 __r) { afterTotalDistributed = __r; } catch { return; }
        uint256 afterTotalRemaining;
        try c.totalRemaining() returns (uint256 __r) { afterTotalRemaining = __r; } catch { return; }
        bool afterBlacklist;
        try c.blacklist(address(this)) returns (bool __r) { afterBlacklist = __r; } catch { return; }
        assertTrue((didRevert && afterCallerBalance == beforeCallerBalance && afterTotalDistributed == beforeTotalDistributed && afterTotalRemaining == beforeTotalRemaining && afterBlacklist == beforeBlacklist)
            ||
            // Case: succeeded -> deltas are consistent
            (!didRevert && (
                // compute deltas
                (afterCallerBalance >= beforeCallerBalance) &&
                (afterTotalDistributed >= beforeTotalDistributed) &&
                (beforeTotalRemaining >= afterTotalRemaining) &&
                // increase in caller balance equals increase in totalDistributed
                ((afterCallerBalance - beforeCallerBalance) == (afterTotalDistributed - beforeTotalDistributed)) &&
                // decrease in totalRemaining equals same amount
                ((beforeTotalRemaining - afterTotalRemaining) == (afterTotalDistributed - beforeTotalDistributed)) &&
                // if any tokens were given then caller is blacklisted afterwards
                (((afterCallerBalance - beforeCallerBalance) > 0) ? (afterBlacklist == true) : (afterBlacklist == beforeBlacklist))
            )));
    }

    function testFuzz_run(uint256 sendAmount) public {
        _run(sendAmount);
    }

    receive() external payable { }
}
